/** The best verse in a chapter, and how well it stands alone. */
export function versePick(book: string, chapter: number): { verse: number; score: number } {
  const rows = VERSE_PICKS[book];
  if (!rows || chapter < 1 || chapter > rows.length) return { verse: 1, score: -Infinity };
  const [verse, score] = rows[chapter - 1];
  return { verse, score };
}
